function back(i,selected=false){return `<button class="back card-pick" data-pick="${i}" aria-label="${tr('Card','Kartu')} ${i+1} ${tr('of','dari')} 8" aria-pressed="${selected}">${choiceMark(i,state?.round||0)}<span class="card-number" aria-hidden="true">${String(i+1).padStart(2,'0')}</span></button>`}
function front(c){return `<div class="revealed-card"><img src="${c.image}" alt="${esc(c.title[lang])}"/><div class="card-category">${esc(c.category)}</div><div class="card-title">${esc(c.title[lang])}</div></div>`}
function top(){document.documentElement.lang=lang;const plotLink=document.querySelector('#plot-twist-link');if(plotLink)plotLink.textContent=tr('Explore PLOT TWIST','Jelajahi PLOT TWIST');const b=document.querySelector('#companion-toggle');if(b){b.textContent=tr('Starlight','Cahaya bintang');b.setAttribute('aria-label',tr('Toggle the cursor star companion','Aktifkan atau nonaktifkan bintang pendamping kursor'))}document.querySelectorAll('[data-lang]').forEach(b=>{b.classList.toggle('active',b.dataset.lang===lang);b.setAttribute('aria-pressed',b.dataset.lang===lang)});}
function render(){top();if(state.revealed&&book&&!showIntro){renderReading();return}if(!state.started||showIntro){app.innerHTML=`<section class="hero"><button class="hero-art" type="button" data-fish-play aria-label="${tr('Invite the fish to swim','Ajak ikannya berenang')}"><div class="fish-current"></div><div class="fish-orbit"></div><img class="hero-fish-swimmer" src="/plottwist/prologue/hero-fish.png?v=swimming" alt="" draggable="false"><span class="hero-droplet droplet-one"></span><span class="hero-droplet droplet-two"></span><span class="hero-droplet droplet-three"></span><span class="fish-play-note">${tr('Tap the water to invite a little movement.','Ketuk airnya untuk mengajak ikan ini berenang.')}</span></button><div class="hero-content"><div class="eyebrow">${tr('Your story begins before chapter one','Kisahmu dimulai sebelum bab pertama')}</div><h1>THE<em>PROLOGUE</em></h1><p class="tagline">${tr('Every story begins somewhere, and yours is waiting to unfold.','Setiap kisah memiliki awal, dan kisahmu menunggu untuk terungkap.')}</p><p class="invitation">${tr("Before the first chapter of PLOT TWIST begins, you're invited to discover a story shaped by the choices you make.",'Sebelum bab pertama PLOT TWIST dimulai, kamu diundang menemukan kisah yang terbentuk dari pilihan-pilihanmu.')}</p><button class="primary" data-action="begin">${tr('Begin the Prologue','Mulai Prologmu')}</button><span class="access-note">${tr('An exclusive gift for the PLOT TWIST experience.','Hadiah eksklusif untuk pengalaman PLOT TWIST.')}</span></div><span class="art-caption">${tr('There is a story taking shape.','Ada kisah yang sedang terbentuk.')}</span></section><section class="welcome-bottom"><div><div class="eyebrow">${tr('A little curiosity goes a long way','Berawal dari rasa ingin tahu')}</div><h2>${tr('Somewhere between a choice and a possibility.','Di antara pilihan dan kemungkinan.')}</h2><div class="mini-backs" aria-hidden="true">${'<div class="back"></div>'.repeat(5)}</div></div><div class="welcome-copy"><p>${tr('Some stories begin with a decision, while others begin with a question, an unexpected encounter, or a quiet realization that something in life is changing.','Ada kisah yang dimulai dengan keputusan. Ada pula yang bermula dari pertanyaan, pertemuan tak terduga, atau kesadaran hening bahwa sesuatu dalam hidup sedang berubah.')}</p><p>${tr("You'll be presented with a collection of mysterious cards across several rounds. Choose whichever draws your attention, following your curiosity, intuition, or simple preference.",'Kamu akan melihat kumpulan kartu misterius dalam beberapa putaran. Pilih yang menarik perhatianmu, mengikuti rasa ingin tahu, intuisi, atau sekadar kesukaanmu.')}</p><p>${tr("Once you've completed your selections, the cards will reveal how their meanings connect and what kind of story they create together.",'Setelah semua pilihanmu lengkap, kartu-kartu itu akan memperlihatkan bagaimana maknanya saling terhubung dan kisah seperti apa yang terbentuk bersama.')}</p></div></section>`;return}
 if(state.stage==='confirm'){app.innerHTML=`<section class="selection"><div class="eyebrow">${tr('Your selections are complete','Pilihanmu sudah lengkap')}</div><h2>${tr('The story is still a mystery.','Kisahnya masih menjadi misteri.')}</h2><p class="round-instruction">${tr('Your selections have come together into a story that is ready to be discovered.','Pilihan-pilihanmu telah membentuk kisah yang siap untuk ditemukan.')}</p><div class="confirmation-cards">${state.selections.map((p,i)=>`<button class="back" data-round="${i}" aria-label="${tr('Revisit round','Kembali ke putaran')} ${i+1}">${choiceMark(p,i)}<span class="card-number" aria-hidden="true">${roman[i]}</span></button>`).join('')}</div><p class="quiet">${tr('You can revisit any selection before revealing your story.','Kamu dapat mengubah pilihan mana pun sebelum mengungkap kisahmu.')}</p><div class="selection-actions"><button class="secondary" data-round="4">${tr('Revisit my choices','Tinjau pilihanku')}</button><button class="primary" data-action="reveal">${tr('Reveal My Prologue','Ungkap Prologku')}</button></div></section>`;return}
 const r=state.round,p=state.selections[r];app.innerHTML=`<section class="selection"><nav class="progress" aria-label="${tr('Selection progress','Kemajuan pilihan')}">${roman.map((n,i)=>`<button class="${i===r?'current':state.selections[i]!==null?'done':''}" data-round="${i}" ${i>r&&state.selections.slice(0,i).includes(null)?'disabled':''} aria-label="${tr('Round','Putaran')} ${i+1}${state.selections[i]!==null?tr(', selected',', sudah dipilih'):''}" ${i===r?'aria-current="step"':''}>${n}</button>`).join('')}</nav><div class="eyebrow">${tr('Round','Putaran')} ${roman[r]} ${tr('of five','dari lima')}</div><h2>${tr('Let your curiosity choose.','Biarkan rasa ingin tahumu memilih.')}</h2><p class="round-instruction">${instructions[lang][r]}</p><p class="quiet">${tr('The cards will remain a mystery until every choice is made.','Kartu-kartu ini tetap menjadi misteri sampai semua pilihan selesai.')}</p><div class="card-grid" role="group" aria-label="${tr('Choose one of eight cards','Pilih satu dari delapan kartu')}">${Array.from({length:8},(_,i)=>back(i,p===i)).join('')}</div><div class="selection-status" aria-live="polite">${p!==null?tr('Your selection is saved. You can still change your mind.','Pilihanmu tersimpan. Kamu masih bisa mengubahnya.'):tr('Take your time. There is no right or wrong choice.','Luangkan waktumu. Tidak ada pilihan yang benar atau salah.')}</div><div class="selection-actions">${r>0?`<button class="secondary" data-round="${r-1}">${tr('Previous round','Putaran sebelumnya')}</button>`:''}<button class="primary" data-action="continue" ${p===null?'disabled':''}>${r===4?tr('Complete my selections','Lengkapi pilihanku'):tr('Continue to the next round','Lanjut ke putaran berikutnya')}</button></div></section>`;}
function paras(a){return a.map(p=>`<p>${esc(p)}</p>`).join('')}
function renderReading(){const b=book;app.innerHTML=`<article class="reading"><div class="reading-header"><div class="eyebrow">${tr('Your prologue has unfolded','Prologmu telah terungkap')}</div><h1>${esc(b.title)}</h1><p class="reflection-note">${tr('Use this reading to think about one real situation in your life. Keep what helps and set aside what does not fit.','Kamu bisa memakai bacaan ini untuk memikirkan satu persoalan dalam hidupmu. Ambil bagian yang berguna dan tinggalkan yang tidak sesuai.')}</p></div><div class="confirmation-cards">${b.cards.map(front).join('')}</div><div class="reading-toolbar"><button class="secondary" data-action="copy">${tr('Copy full reading','Salin seluruh bacaan')}</button><button class="secondary" data-action="share">${tr('Share my prologue','Bagikan prologku')}</button></div><p class="quiet" style="text-align:center">${state.persistent===false?tr('Your reading is available in this session. Copy it if you want to keep it.','Bacaanmu tersedia dalam sesi ini. Salin jika ingin menyimpannya.'):tr('Your reading is saved in this browser.','Bacaanmu tersimpan di peramban ini.')}</p><nav class="reading-nav"><a href="#prologue">${tr('YOUR PROLOGUE','PROLOGMU')}</a><a href="#pieces">${tr('YOUR CARDS','KARTU-KARTUMU')}</a><a href="#pattern">${tr('THE PATTERN','POLA YANG MUNCUL')}</a><a href="#twist">PLOT TWIST</a><a href="#chapter">CHAPTER ZERO</a></nav><section class="reading-section" id="prologue"><div class="eyebrow">A · ${tr('Your Prologue','Prologmu')}</div><h2>${esc(b.title)}</h2>${paras(b.narrative)}</section><section class="reading-section" id="pieces"><div class="eyebrow">B · ${tr('What Your Cards Mean','Arti Kartu-Kartumu')}</div><h2>${tr('How each card contributes.','Peran setiap kartu dalam bacaanmu.')}</h2>${b.cards.map(c=>`<div class="piece"><img loading="lazy" src="${c.image}" alt="${esc(c.title[lang])}"><div><div class="eyebrow">${esc(c.category)}</div><h3>${esc(c.title[lang])}</h3><p>${esc(c.contribution)}</p><details><summary>${tr('A question and something to try','Pertanyaan dan hal yang bisa dicoba')}</summary><p>${esc(c.question[lang])}</p><p><strong>${tr('Try this','Coba ini')}:</strong> ${esc(c.action[lang])}</p></details></div></div>`).join('')}</section><section class="reading-section" id="pattern"><div class="eyebrow">C · ${tr('A Pattern to Consider','Pola yang Bisa Diperhatikan')}</div><h2>${tr('What might be worth noticing.','Hal yang mungkin perlu diperhatikan.')}</h2>${paras(b.hidden)}</section><section class="reading-section twist" id="twist"><div class="eyebrow">D · The Plot Twist</div><h2>${tr('One assumption to reconsider.','Satu anggapan yang bisa ditinjau kembali.')}</h2><p>${esc(b.twist)}</p></section><section class="reading-section chapter" id="chapter"><div class="eyebrow">E · ${tr('Your Chapter Zero','Chapter Zero-mu')}</div><h2>${esc(b.assignment.title)}</h2><p>${esc(b.assignment.objective)}</p><ol>${b.assignment.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p>${esc(b.assignment.question)}</p></section><section class="reading-section closing"><div class="eyebrow">F · ${tr('Closing Reflection','Refleksi Penutup')}</div><p>${esc(b.closing)}</p></section><section class="event"><div class="eyebrow">PLOT TWIST · 14–25 DECEMBER 2026</div><h2>${tr('Your story has already begun.','Kisahmu sudah dimulai.')}</h2><p>${tr('Your story has already begun, and the first chapter of PLOT TWIST opens on December 14.','Kisahmu sudah dimulai, dan bab pertama PLOT TWIST dibuka pada 14 Desember.')}</p><div class="countdown" id="countdown"></div><p>${tr('You can return to this reading throughout the experience.','Kamu dapat kembali ke bacaan ini sepanjang pengalaman berlangsung.')}</p><button class="text-button" data-action="restart">${tr('Begin another prologue','Mulai prolog lainnya')}</button></section></article>`;countdown()}
function countdown(){const e=$('#countdown');if(!e)return;const d=Math.max(0,new Date('2026-12-14T00:00:00+07:00')-Date.now()),days=Math.floor(d/86400000),hours=Math.floor(d/3600000)%24,min=Math.floor(d/60000)%60;e.innerHTML=(d?`${days} ${tr('days','hari')} · ${hours} ${tr('hours','jam')} · ${min} ${tr('minutes','menit')}`:tr('The first chapter is open.','Bab pertama telah dibuka.'))+`<small>14 ${tr('DECEMBER','DESEMBER')} 2026 · 00:00 WIB · ASIA/JAKARTA</small>`}setInterval(countdown,30000);
function fullText(){const b=book;return ['THE PROLOGUE',b.title,...b.narrative,tr('What Your Cards Mean','Arti Kartu-Kartumu'),...b.cards.flatMap(c=>[c.title[lang],c.contribution,c.question[lang],c.action[lang]]),tr('A Pattern to Consider','Pola yang Bisa Diperhatikan'),...b.hidden,'The Plot Twist',b.twist,b.assignment.title,b.assignment.objective,...b.assignment.steps,b.assignment.question,b.closing,tr('Your story has already begun, and the first chapter of PLOT TWIST opens on December 14.','Kisahmu sudah dimulai, dan bab pertama PLOT TWIST dibuka pada 14 Desember.'),'© 2026 Pearling Lim. All Rights Reserved'].join('\n\n')}
async function copy(text){try{await navigator.clipboard.writeText(text)}catch{const e=document.createElement('textarea');e.value=text;document.body.append(e);e.select();if(!document.execCommand('copy')){e.remove();throw Error(tr('Copy is unavailable in this browser. You can select and copy the reading text directly.','Penyalinan tidak tersedia di peramban ini. Kamu bisa memilih dan menyalin teks bacaannya langsung.'))}e.remove()}}
app.addEventListener('keydown',e=>{if(e.target.matches('[data-pick]')&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key)){e.preventDefault();const n=Number(e.target.dataset.pick),cols=innerWidth<=800?4:8;let next=e.key==='Home'?0:e.key==='End'?7:(n+({'ArrowLeft':-1,'ArrowRight':1,'ArrowUp':-cols,'ArrowDown':cols}[e.key])+8)%8;$(`[data-pick="${next}"]`).focus()}});
app.addEventListener('click',async e=>{if(e.target.closest('[data-fish-play]')){playFish(e);return}const b=e.target.closest('button');if(!b||b.disabled||busy)return;busy=true;try{if(b.dataset.pick!==undefined){const n=Number(b.dataset.pick);state=await api('choose',{round:state.round,position:n});render();$(`[data-pick="${n}"]`)?.focus()}else if(b.dataset.round!==undefined){state=await api('navigate',{round:Number(b.dataset.round)});render()}else {switch(b.dataset.action){case'begin':showIntro=false;state=await api('begin',{});render();window.scrollTo(0,0);break;case'continue':state=await api('navigate',state.round===4?{stage:'confirm'}:{round:state.round+1});render();window.scrollTo(0,0);break;case'reveal':{if(!await confirmReveal())break;const r=await api('reveal',{});book=r.reading;state=r.state;revealing=true;app.innerHTML=`<section class="selection"><div class="eyebrow">${tr('Your story is unfolding','Kisahmu sedang terungkap')}</div><h2>${tr('Meet the pieces of your story.','Temukan bagian-bagian kisahmu.')}</h2><div class="confirmation-cards reveal-stage">${state.selections.map((p,i)=>'<div class="back">'+choiceMark(p,i)+'</div>').join('')}</div><p class="quiet" aria-live="polite" id="reveal-status"></p></section>`;const slots=[...document.querySelector('.reveal-stage').children];for(let i=0;i<5;i++){if(!matchMedia('(prefers-reduced-motion: reduce)').matches)await new Promise(r=>setTimeout(r,650));slots[i].outerHTML=front(book.cards[i]);$('#reveal-status').textContent=book.cards[i].title[lang]}if(!matchMedia('(prefers-reduced-motion: reduce)').matches)await new Promise(r=>setTimeout(r,1000));revealing=false;render();window.scrollTo(0,0);break}case'copy':await copy(fullText());toast(tr('Your full reading has been copied.','Seluruh bacaanmu sudah disalin.'));break;case'share':{const text=book.title+'\n\n'+book.cards.map(c=>c.title[lang]).join(' · ')+'\n\n'+tr('My prologue, an original experience created for PLOT TWIST.','Prologku, pengalaman orisinal yang diciptakan untuk PLOT TWIST.');if(navigator.share){try{await navigator.share({title:'THE PROLOGUE',text})}catch(err){if(err.name!=='AbortError')throw err}}else{await copy(text);toast(tr('Your shareable summary has been copied.','Ringkasan untuk dibagikan sudah disalin.'))}break}case'restart':if(confirm(tr('Begin again? This replaces your current reading. Copy it first if you want to keep it.','Mulai lagi? Ini akan mengganti bacaanmu sekarang. Salin dahulu jika kamu ingin menyimpannya.'))){state=await api('restart',{});book=null;render();window.scrollTo(0,0)}break}}}catch(err){toast(err.message)}finally{busy=false}});
document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',async()=>{if(busy||revealing)return;const old=lang;lang=b.dataset.lang;try{if(state?.revealed){book=(await api('reading')).reading}try{localStorage.setItem('prologue-language',lang)}catch{}render()}catch(err){lang=old;toast(err.message)}}));
document.querySelector('.brand').addEventListener('click',e=>{if(!state||busy)return;e.preventDefault();showIntro=true;render();window.scrollTo(0,0)});
async function init(){try{state=await api('session');if(state.revealed)book=(await api('reading')).reading;render()}catch(err){app.innerHTML=`<section class="selection"><h2>${tr('Your story is still here.','Kisahmu masih di sini.')}</h2><p>${esc(err.message)}</p><button class="primary" id="retry">${tr('Try again','Coba lagi')}</button></section>`;$('#retry').onclick=init}}init();

// A single animation loop, with a short reusable trail. No pointer interception.
const companion=document.createElement('div');companion.id='cursor-companion';companion.setAttribute('aria-hidden','true');companion.innerHTML='<div class="cursor-aura"></div><div class="cursor-star"></div>';
document.body.append(companion);
const control=document.createElement('button');control.id='companion-toggle';control.className='companion-toggle';control.type='button';control.textContent=tr('Starlight','Cahaya bintang');document.body.append(control);
let companionEnabled=true;try{companionEnabled=localStorage.getItem('prologue-companion')!=='off'}catch{}
const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)'),finePointer=matchMedia('(pointer: fine)');
let targetX=innerWidth*.75,targetY=innerHeight*.35,starX=targetX,starY=targetY,pointerSeen=false,companionFrame=0,lastTrail=0;
const trail=Array.from({length:10},()=>{const s=document.createElement('i');s.className='cursor-dust';s.setAttribute('aria-hidden','true');document.body.append(s);return {el:s,x:0,y:0,life:0}});let trailIndex=0;
function companionStatus(){control.setAttribute('aria-pressed',String(companionEnabled));control.classList.toggle('off',!companionEnabled);companion.classList.toggle('inactive',!companionEnabled||!finePointer.matches||reduceMotion.matches);if(!companionEnabled||reduceMotion.matches||!finePointer.matches){cancelAnimationFrame(companionFrame);companionFrame=0;for(const p of trail){p.life=0;p.el.style.opacity=0}}else if(!companionFrame)companionFrame=requestAnimationFrame(animateCompanion)}
function animateCompanion(time){if(!companionEnabled||reduceMotion.matches||!finePointer.matches){companionFrame=0;return}starX+=(targetX-starX)*.13;starY+=(targetY-starY)*.13;companion.style.transform=`translate3d(${starX+15}px,${starY-13}px,0)`;companion.style.opacity=pointerSeen?'1':'0';if(pointerSeen&&time-lastTrail>70&&Math.hypot(targetX-starX,targetY-starY)>4){const p=trail[trailIndex++%trail.length];p.x=starX+15;p.y=starY-13;p.life=1;lastTrail=time}for(const p of trail){if(p.life>0){p.life=Math.max(0,p.life-.025);p.el.style.transform=`translate3d(${p.x}px,${p.y+(1-p.life)*20}px,0) scale(${p.life})`;p.el.style.opacity=p.life*.7}}companionFrame=requestAnimationFrame(animateCompanion)}
window.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;pointerSeen=true;targetX=e.clientX;targetY=e.clientY;const hero=document.querySelector('.hero');if(hero){const r=hero.getBoundingClientRect(),inside=e.clientY>=r.top&&e.clientY<=r.bottom;if(inside&&!reduceMotion.matches){hero.style.setProperty('--drift-x',((e.clientX/innerWidth-.5)*14)+'px');hero.style.setProperty('--drift-y',((e.clientY/innerHeight-.5)*10)+'px')}}},{passive:true});
document.addEventListener('pointerleave',()=>{pointerSeen=false});control.addEventListener('click',()=>{companionEnabled=!companionEnabled;try{localStorage.setItem('prologue-companion',companionEnabled?'on':'off')}catch{}companionStatus()});reduceMotion.addEventListener('change',companionStatus);finePointer.addEventListener('change',companionStatus);document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAnimationFrame(companionFrame);companionFrame=0}else companionStatus()});companionStatus();

// The fish responds to taps, mouse clicks, and keyboard activation without changing the reading.
let fishSwimAnimation;
function playFish(event){const pool=event.target.closest('[data-fish-play]');if(!pool)return;const r=pool.getBoundingClientRect(),keyboard=event.detail===0,x=keyboard?r.width*.64:event.clientX-r.left,y=keyboard?r.height*.38:event.clientY-r.top;const dx=Math.max(-65,Math.min(65,(x/r.width-.5)*110)),dy=Math.max(-50,Math.min(50,(y/r.height-.5)*90));const ripple=document.createElement('span');ripple.className='fish-ripple';ripple.style.left=(x/r.width*100)+'%';ripple.style.top=(y/r.height*100)+'%';ripple.setAttribute('aria-hidden','true');pool.append(ripple);setTimeout(()=>ripple.remove(),1500);if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;fishSwimAnimation?.cancel();const swimmer=pool.querySelector('.hero-fish-swimmer');const base=getComputedStyle(swimmer).transform;fishSwimAnimation=swimmer.animate([{transform:base},{transform:`translate3d(${dx*1.5}px,${dy*1.5-35}px,0) rotate(${dx>0?9:-12}deg) scale(1.07)`,offset:.4},{transform:`translate3d(${-dx*.35}px,${dy*.3}px,0) rotate(${-dx/20}deg) scale(.96)`,offset:.72},{transform:base}],{duration:1900,easing:'cubic-bezier(.2,.65,.25,1)'});for(let i=0;i<5;i++){const drop=document.createElement('span');drop.className='fish-bubble';drop.setAttribute('aria-hidden','true');drop.style.left=(x/r.width*100+(i-2)*3)+'%';drop.style.top=(y/r.height*100+5)+'%';drop.style.animationDelay=(i*.07)+'s';pool.append(drop);setTimeout(()=>drop.remove(),1700)}}

function confirmReveal(){return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.className='reveal-disclaimer';dialog.setAttribute('aria-labelledby','before-reveal-title');dialog.innerHTML=`<div class="eyebrow">THE PROLOGUE</div><h2 id="before-reveal-title">${tr('Before your story unfolds...','Sebelum kisahmu terungkap...')}</h2><p>${tr('You have just created one of 32,768 possible combinations through a game of intuition, chance, and personal interpretation.','Kamu baru saja membentuk satu dari 32.768 kemungkinan kombinasi melalui permainan intuisi, kebetulan, dan penafsiran pribadi.')}</p><p>${tr('The probability of arriving at your exact combination is 1 in 32,768, assuming every card is equally likely to be selected.','Peluang mendapatkan kombinasi persis seperti milikmu adalah 1 dari 32.768, dengan asumsi setiap kartu memiliki peluang yang sama untuk dipilih.')}</p><p>${tr('What follows is a symbolic narrative for you to explore, question, and make your own.','Setelah ini, kamu akan membaca sebuah narasi simbolis yang bebas kamu jelajahi, pertanyakan, dan maknai sendiri.')}</p><div class="disclaimer-actions"><button type="button" class="primary" data-disclaimer-confirm autofocus>${tr('Reveal My Prologue','Ungkap Prologku')}</button><button type="button" class="text-button" data-disclaimer-cancel>${tr('Return to my cards','Kembali ke kartu-kartuku')}</button></div>`;const finish=value=>{dialog.close();dialog.remove();resolve(value)};dialog.querySelector('[data-disclaimer-confirm]').onclick=()=>finish(true);dialog.querySelector('[data-disclaimer-cancel]').onclick=()=>finish(false);dialog.addEventListener('cancel',event=>{event.preventDefault();finish(false)},{once:true});document.body.append(dialog);dialog.showModal()})}
